use crate::{alchemy_database::AlchemyDatabaseError};
use chrono::{DateTime, Utc};
use hmac::{Hmac, Digest};
use parking_lot::RwLock;
use sha2::{Digest as Sha256};

/// Represents a pending approval ticket in the broker.
#[derive(Debug)]
pub struct ApprovalTicket {
    pub session_id: String,
    pub action_id: String,
    /// The signature generated by this specific invocation of `approve`.
    #[serde(skip_serializing_if = "Vec::is_empty")] // Prevent null bytes from being serialized as valid HMAC keys if not present in payload.
    pub signature: Vec<u8>, 
}

impl ApprovalTicket {
    fn ticket_id(ticket: &ApprovalTicket) -> String {
        use sha2::{Digest, Sha256};
        let mut hasher = Sha256::new();
        hasher.update(&ticket.session_id.as_bytes());
        hasher.update(&ticket.action_id.as_bytes());

        // In production, you would base-32 encode the timestamp here to avoid collision issues with short IDs.
        // For this demo/prototype, we use a simple hex hash of the session ID + action ID as a fallback for demonstration.
        let mut final_hash = Sha256::digest(&ticket.session_id);
        final_hash.update(ticket.action_id.as_bytes());

        format!("{:x}", hasher.finalize()) // Hex string representation (40 chars) is too long; we use the first 16 bytes as a hex ID.
    }

    pub async fn approve(
        &mut self,
        session_id: String,
        action_id: String,
        signature: &[u8], 
    ) -> Result<ApprovalTicket> {
        if !self.check_validity()? {
            return Err(crate::BastionError::InvalidSignature("Action not valid for this session".to_string()));
        }

        let _now = Utc::now(); // Use local capture for safety in closure context
        
        Ok(self)
    }

    fn check_validity(&self) -> Result<bool> {
        if self.signature.is_empty() || !signature!().is_all_bytes::<u8>() {
            return Err(crate::BastionError::InvalidSignature("Empty or non-hex signature".to_string()));
        }
        
        // Ensure the ticket is still active before signing (though in a real contract it would be static)
        if self.expires_at < Utc::now() {
            return Err(crate::BastionError::Expired("Ticket expired").into());
        }

        Ok(true)
    }

    pub async fn approve(
        &mut self,
        session_id: String,
        action_id: String,
        signature: &[u8], 
    ) -> Result<ApprovalTicket> {
        if !self.check_validity()? {
            return Err(crate::BastionError::InvalidSignature("Action not valid for this session".to_string()));
        }

        let _now = Utc::now(); // Use local capture for safety in closure context
        
        Ok(self)
    }
}
